def get_numbers():        a = int(input("Enter first number:"))    b = int(input("Enter second number:"))    return a, b def save_result(text):    with open("history.txt", "a") as f:        f.write(text + "\n")            def show_history():        try:        with open("history.txt", "r") as f:            context = f.read()                        if context == "":                print("No history yet.")                        else:                print("---History---")                print(context)            except FileNotFoundError:        print("No history file found yet.")                def clear_history():    with open("history.txt", "w") as f:            f.write("")            print("History cleared")        def handle_command(command):        command = command.strip().lower()        if command == "q":        print("Goodbye")        return "quit"        if command == "history":        show_history()        return "continue"        if command == "clear":        clear_history()        return "continue"        if command == "help":        show_help()        return "continue"        if command == "":        return "calculate"        print("Unknown command. Type help to see available cammands.")    return "continue"def show_help():    print("\n---Help---")    print("Enter   : calculate with two numbers")    print("history : show calculation history")    print("clear   : clear calculation history")    print("q       : quit the program")                                             